const { sessionFromEvent } = require('./_lib/rag-auth');

const RELEASE = '10.1.0-langgraph-native-ui-r1';
const HTML = "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>RAG · Production UI</title>\n<style>\n:root{\n  --bg:#06101c;--panel:#0b1a2d;--panel2:#0d2239;--line:#24598f;--line2:#173d66;\n  --blue:#2563eb;--cyan:#38bdf8;--text:#eaf5ff;--muted:#7fa9ce;--done:#123d70;\n}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--text);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}\nbutton,input,select{font:inherit}\nbutton{cursor:pointer}\n.hidden{display:none!important}\n.shell{min-height:100vh;background:linear-gradient(180deg,#081827,#06101c)}\n.top{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:14px 18px;background:#091828;border-bottom:1px solid var(--line2);position:sticky;top:0;z-index:20}\n.brand{font-size:12px;font-weight:800;letter-spacing:.15em;color:#dbeeff}.ver{font-size:10px;color:var(--muted);margin-top:2px}\n.modebar,.viewbar,.tools{display:flex;gap:7px;flex-wrap:wrap;align-items:center}\n.pill,.toolbtn{border:1px solid #285b8f;border-radius:999px;background:#0d2138;color:#8fb4d8;padding:8px 11px;font-size:11px;min-height:38px}\n.toolbtn.square{width:38px;padding:0;text-align:center;font-size:18px;font-weight:800}\n.pill.on,.toolbtn.on{background:#1d4ed8;border-color:#60a5fa;color:#fff;box-shadow:0 0 18px rgba(37,99,235,.23)}\n.pill.locked{cursor:default;opacity:1}.pill.locked::after{content:' · CORE';font-size:8px;letter-spacing:.08em;color:#bfdbfe}\n.tabs{display:flex;gap:6px;padding:10px 14px;background:#081523;border-bottom:1px solid var(--line2);overflow-x:auto;position:sticky;top:67px;z-index:15}\n.tab{white-space:nowrap;border:1px solid transparent;border-radius:9px;background:transparent;color:#78a4cb;padding:9px 12px;font-size:11px;min-height:40px}\n.tab.on{background:#102844;border-color:#285b8f;color:#edf7ff;font-weight:800}\n.main{padding:14px;min-width:0}\n.section{max-height:calc(100vh - 140px);overflow-y:auto;overflow-x:hidden;padding-right:5px;scrollbar-gutter:stable}\n.titlebar{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:10px}\n.titlebar strong{font-size:12px;letter-spacing:.06em}\n.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}\n.card{background:var(--panel);border:1px solid #1b4772;border-radius:12px;padding:12px;min-width:0}\n.card h3{margin:0 0 9px;font-size:11px;letter-spacing:.08em;color:#b9ddff;font-weight:800}\nlabel{display:block;font-size:10px;color:var(--muted);margin:8px 0 4px}\ninput,select{width:100%;background:#071522;border:1px solid var(--line);color:#e7f4ff;border-radius:8px;padding:9px 10px;font-size:15px;min-height:40px}\n.split{display:grid;grid-template-columns:1fr 1fr;gap:8px}.stats{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.stat{background:#071522;border:1px solid #1d4770;border-radius:8px;padding:9px;font-size:11px;color:#dceeff}.stat span{display:block;font-size:9px;color:#6e9bc3;margin-bottom:2px}\n.apply,.send{background:#2563eb;border:1px solid #60a5fa;color:#fff;border-radius:8px;padding:9px 14px;font-size:11px;font-weight:800;min-height:40px}\n.status{font-size:10px;color:#78a4cb}\n\n/* CHAT ARRIBA */\n.chatCard{margin-bottom:12px}\n.chat{height:180px;overflow-y:auto;background:#06111d;border:1px solid #1d4770;border-radius:10px;padding:10px;font-size:11px;scrollbar-gutter:stable}\n.msg{padding:7px 0;border-bottom:1px solid #102d4b;color:#c9e5ff}.composer{display:grid;grid-template-columns:1fr auto;gap:7px;margin-top:8px}\n\n/* DIAGRAMA ABAJO */\n.diagramCard{min-width:0}\n.diagramHeader{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:8px}\n.canvasFrame{border:1px solid #1b4772;border-radius:12px;background:#06111d;overflow:auto;height:760px;padding:10px;scrollbar-gutter:stable both-edges}\n.canvasFrame.booting .zoomStage{opacity:0}\n.zoomStage{transition:opacity .12s ease}\n.zoomStage{transform-origin:top left;transform:scale(1);width:1420px;height:1120px}\n.canvas{position:relative;width:1400px;height:1080px;background-image:linear-gradient(rgba(36,89,143,.10) 1px,transparent 1px),linear-gradient(90deg,rgba(36,89,143,.10) 1px,transparent 1px);background-size:24px 24px;border-radius:8px}\nsvg.edges{position:absolute;inset:0;width:1400px;height:1080px;overflow:visible;pointer-events:none}\n.edge{stroke:#24598f;stroke-width:2;fill:none;marker-end:url(#arrowhead);opacity:.85;transition:.18s}\n.edge.active{stroke:#38bdf8;stroke-width:3;filter:drop-shadow(0 0 4px rgba(56,189,248,.65))}\n.edge.inflight{stroke:#38bdf8;stroke-width:2.7;stroke-dasharray:8 8;animation:edgeFlow .8s linear infinite;filter:drop-shadow(0 0 3px rgba(56,189,248,.55))}\n.edge.done{stroke:#3b82f6;stroke-width:2.5}\n@keyframes edgeFlow{to{stroke-dashoffset:-32}}\n.node{position:absolute;width:180px;min-height:66px;background:#0b1b31;border:1px solid #285b8f;border-radius:10px;color:#9fc7e9;user-select:none;display:flex;align-items:stretch;transition:.15s;z-index:2;overflow:hidden}\n.node b{font-size:10px;letter-spacing:.04em}.node small{font-size:8px;color:#618caf;margin-top:4px;line-height:1.3}\n.node.active{background:#123d70;border-color:#7dd3fc;color:#fff;box-shadow:0 0 0 2px rgba(59,130,246,.18),0 0 24px rgba(56,189,248,.38)}\n.node.inflight{border-color:#38bdf8;color:#eaf8ff;box-shadow:0 0 0 1px rgba(56,189,248,.22),0 0 20px rgba(56,189,248,.24);animation:nodePulse 1.15s ease-in-out infinite}\n.node.done{background:#0f2f52;border-color:#3b82f6;color:#e1f2ff}\n@keyframes nodePulse{0%,100%{filter:brightness(1)}50%{filter:brightness(1.28)}}\n.node.selected{outline:2px solid #38bdf8;outline-offset:2px}\n.info{margin-top:9px;border:1px solid var(--line);background:#08192a;border-radius:10px;padding:10px;height:120px;overflow-y:auto;scrollbar-gutter:stable}\n.info.collapsed{display:none}.info strong{font-size:11px;color:#bfe2ff}.info p{margin:5px 0 0;color:#7fa9ce;font-size:10px;line-height:1.45}\n.legend{display:flex;gap:12px;flex-wrap:wrap;margin-top:7px;font-size:9px;color:#6f9bc4}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:4px}\n\n.nodebody{flex:1;border:0;background:transparent;color:inherit;padding:9px 8px;text-align:center;cursor:pointer;display:flex;flex-direction:column;justify-content:center;align-items:center}\n.nodebody b{font-size:11px;letter-spacing:.03em}\n.nodebody small{display:block;margin-top:4px;color:#7fa9ce;font-size:9px;line-height:1.3}\n.nodeinfo{\n  width:34px;min-width:34px;height:34px;margin:auto 10px auto 0;border:1px solid #3a76aa;border-radius:999px;\n  background:linear-gradient(180deg,#143152 0%,#0d2239 100%);color:#d8efff;font-weight:800;font-size:14px;cursor:pointer;\n  display:flex;align-items:center;justify-content:center;box-shadow:0 6px 18px rgba(0,0,0,.24), inset 0 1px 0 rgba(255,255,255,.06);\n  transition:transform .15s ease, background .15s ease, box-shadow .15s ease, color .15s ease\n}\n.nodeinfo:hover{background:linear-gradient(180deg,#194069 0%,#13304e 100%);color:#ffffff;transform:translateY(-1px);box-shadow:0 10px 24px rgba(0,0,0,.28), inset 0 1px 0 rgba(255,255,255,.08)}\n.nodeinfo:active{transform:translateY(0)}\n.nodepopover{\n  position:absolute;z-index:12;width:280px;max-width:280px;background:rgba(8,25,42,.98);\n  border:1px solid #2f6ea4;border-radius:14px;padding:14px 14px 12px;box-shadow:0 16px 40px rgba(0,0,0,.34);\n  color:#dcefff;display:none\n}\n.nodepopover.open{display:block}\n.nodepopover h4{margin:0 0 8px;font-size:13px;letter-spacing:.08em;color:#dff2ff}\n.nodepopover p{margin:0 0 8px;font-size:10.5px;line-height:1.55;color:#9fc7e9}\n.nodepopover .meta{font-size:10px;color:#79afdd}\n.nodepopover .closemini{\n  margin-top:6px;border:1px solid #2e6a9b;border-radius:999px;background:#0d2239;color:#bfe2ff;\n  padding:6px 10px;font-size:10px;cursor:pointer\n}\n.nodepopover .closemini:hover{background:#12345a;color:#fff}\n\n\n.fieldrow{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:8px;position:relative}\n.fieldrow label{margin:0}\n.helpbtn{\n  width:26px;height:26px;border:1px solid #3a76aa;border-radius:999px;\n  background:linear-gradient(180deg,#143152 0%,#0d2239 100%);color:#d8efff;font-weight:800;font-size:12px;cursor:pointer;\n  display:inline-flex;align-items:center;justify-content:center;padding:0;\n  box-shadow:0 6px 16px rgba(0,0,0,.22), inset 0 1px 0 rgba(255,255,255,.06);\n  transition:transform .15s ease, background .15s ease, box-shadow .15s ease, color .15s ease\n}\n.helpbtn:hover{background:linear-gradient(180deg,#194069 0%,#13304e 100%);color:#ffffff;transform:translateY(-1px);box-shadow:0 10px 20px rgba(0,0,0,.25), inset 0 1px 0 rgba(255,255,255,.08)}\n.helpbtn:active{transform:translateY(0)}\n.fieldhelp{\n  display:none;position:absolute;z-index:60;right:0;top:34px;width:min(390px,calc(100vw - 72px));margin:0;\n  padding:14px 15px;border:1px solid #3477ad;background:rgba(8,25,42,.985);border-radius:12px;\n  color:#b7d7f1;font-size:10.5px;line-height:1.62;box-shadow:0 18px 42px rgba(0,0,0,.38),inset 0 1px 0 rgba(255,255,255,.04)\n}\n.fieldhelp::before{content:\"\";position:absolute;right:8px;top:-6px;width:10px;height:10px;background:#0b2036;border-left:1px solid #3477ad;border-top:1px solid #3477ad;transform:rotate(45deg)}\n.fieldhelp.open{display:block}\n.stat{cursor:pointer}\n.stat .statdetail{display:none;margin-top:5px;color:#91b9dc;font-size:9px;line-height:1.4}\n.stat.open .statdetail{display:block}\n\n@media(max-width:760px){.grid2,.split{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}.tabs{top:101px}}\n</style>\n</head>\n<body>\n<div class=\"shell\">\n  <div class=\"top\">\n    <div><div class=\"brand\">RAG / DOCUMENT INTELLIGENCE</div><div class=\"ver\">BACKEND · UI TREE · NO REORDER · LIVE</div></div>\n    <div class=\"modebar\">\n      <button type=\"button\" class=\"pill on\" data-mode=\"rag\">RAG</button>\n      <button type=\"button\" class=\"pill on locked\" data-mode=\"llm\" aria-disabled=\"true\" title=\"LLM ORCHESTRATOR · siempre activo\">LLM</button>\n      <button type=\"button\" class=\"pill\" data-mode=\"agent\">AGENT</button>\n    </div>\n  </div>\n\n  <div class=\"tabs\">\n    <button class=\"tab on\" data-page=\"config\">01 CONFIGURATION</button>\n    <button class=\"tab\" data-page=\"workflow\">02 CHAT + LIVE WORKFLOW</button>\n    <button id=\"agentTab\" class=\"tab hidden\" data-page=\"agent\">03 AGENT</button>\n  </div>\n\n  <main class=\"main\">\n    <section id=\"page-config\" class=\"section\">\n      <div class=\"titlebar\"><strong>RAG CONFIGURATION</strong><span class=\"status\">parámetros productivos completos</span></div>\n      <div class=\"grid2\">\n        <div class=\"card\"><h3>MODEL PLANE</h3>\n          <div class=\"fieldrow\"><label>LLM</label><button class=\"helpbtn\" data-help=\"h-llm\">i</button></div>\n          <div id=\"h-llm\" class=\"fieldhelp\">El parámetro LLM define cuál es el modelo principal que redacta la respuesta final. En términos prácticos, este componente determina el tono, la capacidad de razonamiento, la calidad de la redacción y el costo computacional de cada interacción. Cambiar este valor no modifica la arquitectura general, pero sí puede alterar de forma importante la experiencia del usuario, la velocidad de respuesta y la memoria que el sistema necesita para operar con estabilidad.</div>\n          <select><option>qwen3.5:35b-a3b-q4_K_M</option></select>\n\n          <div class=\"fieldrow\"><label>Planner</label><button class=\"helpbtn\" data-help=\"h-planner\">i</button></div>\n          <div id=\"h-planner\" class=\"fieldhelp\">Planner es el componente que toma una solicitud compleja y la traduce a un plan estructurado de trabajo. Su rol no es producir la respuesta definitiva, sino decidir qué pasos deben ejecutarse, en qué orden y con qué contratos. Tener este rol separado ayuda a mantener una arquitectura más limpia, porque reduce improvisación, vuelve auditable el flujo y evita que el modelo principal mezcle planificación con ejecución sin control.</div>\n          <select><option>qwen3.5:35b-a3b-q4_K_M</option></select>\n\n          <div class=\"fieldrow\"><label>Embeddings</label><button class=\"helpbtn\" data-help=\"h-embed\">i</button></div>\n          <div id=\"h-embed\" class=\"fieldhelp\">Embeddings es el modelo que convierte textos en representaciones vectoriales para poder buscar por significado y no sólo por coincidencia literal de palabras. Gracias a esto, el sistema puede recuperar documentos relacionados aunque la consulta del usuario use otros términos. Elegir bien este componente es clave para la calidad de recuperación, porque un embedding débil degrada toda la cadena RAG aunque el LLM final sea muy bueno.</div>\n          <select><option>nomic-embed-text:latest</option></select>\n\n          <div class=\"split\">\n            <div>\n              <div class=\"fieldrow\"><label>Context</label><button class=\"helpbtn\" data-help=\"h-context\">i</button></div>\n              <div id=\"h-context\" class=\"fieldhelp\">Context indica cuánto contenido puede recibir el modelo en una sola pasada. Un contexto más amplio permite combinar más evidencia, instrucciones y resultados intermedios dentro del mismo turno, pero también aumenta el uso de memoria y puede impactar latencia. Por eso no es un número decorativo: es un límite operativo que afecta directamente hasta dónde puede crecer la complejidad real del sistema.</div>\n              <input type=\"number\" value=\"8192\">\n            </div>\n            <div>\n              <div class=\"fieldrow\"><label>Timeout</label><button class=\"helpbtn\" data-help=\"h-timeout\">i</button></div>\n              <div id=\"h-timeout\" class=\"fieldhelp\">Timeout define el tiempo máximo que se le permite a una operación antes de considerarla fallida. Este parámetro protege al sistema de bloqueos silenciosos, procesos colgados y tiempos de espera indefinidos que degradan la experiencia del usuario. Arquitectónicamente, es importante porque ayuda a que el runtime falle de forma explícita y verificable, en línea con una disciplina de fail-closed y control operacional.</div>\n              <input type=\"number\" value=\"180\">\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card\"><h3>RETRIEVAL</h3>\n          <div class=\"fieldrow\"><label>Mode</label><button class=\"helpbtn\" data-help=\"h-mode\">i</button></div>\n          <div id=\"h-mode\" class=\"fieldhelp\">Mode describe la estrategia base de recuperación. En HYBRID, el sistema combina una búsqueda semántica —basada en significado— con una búsqueda lexical —basada en términos exactos— para aprovechar lo mejor de ambos enfoques. Esto reduce el riesgo de perder coincidencias obvias o, al contrario, de recuperar demasiado ruido cuando una consulta es ambigua o muy específica.</div>\n          <select><option>HYBRID</option><option>SEMANTIC</option><option>LEXICAL</option></select>\n\n          <div class=\"fieldrow\"><label>Fusion</label><button class=\"helpbtn\" data-help=\"h-rrf\">i</button></div>\n          <div id=\"h-rrf\" class=\"fieldhelp\">Fusion define cómo se combinan múltiples rankings parciales en una sola lista final de candidatos. RRF, o Reciprocal Rank Fusion, es una técnica muy usada porque no exige normalizar los scores de cada motor y aun así produce un ranking robusto. En la práctica, esto permite mezclar retrieval semántico y lexical sin acoplar demasiado sus escalas internas ni construir lógica frágil alrededor de puntajes no comparables.</div>\n          <select><option>RRF</option></select>\n\n          <div class=\"fieldrow\"><label>Reranker</label><button class=\"helpbtn\" data-help=\"h-reranker\">i</button></div>\n          <div id=\"h-reranker\" class=\"fieldhelp\">Reranker es una segunda etapa de refinamiento. Primero se recuperan varios candidatos potencialmente útiles y luego este componente los vuelve a ordenar con un criterio más fino de relevancia respecto de la consulta. Su función es mejorar precisión sin encarecer toda la búsqueda inicial. Cuando está bien elegido, reduce respuestas apoyadas en evidencia marginal y eleva la calidad del contexto que finalmente consume el modelo principal.</div>\n          <select><option>BAAI/bge-reranker-v2-m3</option></select>\n\n          <div class=\"split\">\n            <div>\n              <div class=\"fieldrow\"><label>Top-K ceiling</label><button class=\"helpbtn\" data-help=\"h-topk\">i</button></div>\n              <div id=\"h-topk\" class=\"fieldhelp\">Top-K ceiling indica el máximo de candidatos que pueden avanzar desde retrieval hacia las etapas siguientes. No significa que siempre deban pasar exactamente K fragmentos, sino que el sistema no superará ese techo. Este parámetro importa porque controla el balance entre cobertura y ruido: si es demasiado bajo, puede faltar evidencia; si es demasiado alto, el contexto se contamina y la respuesta final se vuelve menos nítida.</div>\n              <input type=\"number\" value=\"8\">\n            </div>\n            <div>\n              <div class=\"fieldrow\"><label>Min evidence</label><button class=\"helpbtn\" data-help=\"h-minev\">i</button></div>\n              <div id=\"h-minev\" class=\"fieldhelp\">Min evidence representa el umbral mínimo para considerar que la evidencia disponible es suficiente. Es una barrera de calidad: evita que el sistema actúe como si estuviera bien respaldado cuando en realidad sólo encontró material débil o ambiguo. Desde el punto de vista del mantra, este tipo de umbral hace que la arquitectura sea más confiable, porque convierte criterios difusos en reglas verificables y repetibles.</div>\n              <input type=\"number\" step=\"0.01\" value=\"0.20\">\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card\"><h3>GROUNDING / CONTRACTS</h3>\n          <div class=\"fieldrow\"><label>Grounding</label><button class=\"helpbtn\" data-help=\"h-grounding\">i</button></div>\n          <div id=\"h-grounding\" class=\"fieldhelp\">Grounding define la política con que el sistema conecta su respuesta con evidencia real. En modo EVIDENCE-ONLY, la idea es que la salida no se sostenga en mera intuición del modelo, sino en material recuperado y autorizado por el pipeline. Esto es especialmente importante en entornos analíticos o corporativos, donde una respuesta elegante pero no respaldada es peor que una respuesta limitada pero trazable.</div>\n          <select><option>EVIDENCE-ONLY</option></select>\n\n          <div class=\"fieldrow\"><label>Evidence gate</label><button class=\"helpbtn\" data-help=\"h-gate\">i</button></div>\n          <div id=\"h-gate\" class=\"fieldhelp\">Evidence gate es una compuerta de control que decide si la evidencia reunida realmente alcanza el estándar exigido para pasar a la etapa de respuesta. Su valor no está en adornar el pipeline, sino en impedir que una recuperación incompleta o marginal se transforme automáticamente en output final. Es una defensa contra el exceso de confianza del sistema y ayuda a preservar disciplina operativa.</div>\n          <select><option>ENABLED</option></select>\n\n          <div class=\"fieldrow\"><label>Verifier</label><button class=\"helpbtn\" data-help=\"h-verifier\">i</button></div>\n          <div id=\"h-verifier\" class=\"fieldhelp\">Verifier es el componente que revisa si la salida producida se mantiene consistente con la evidencia y con los resultados intermedios del flujo. No reemplaza al modelo ni al retrieval, pero introduce una capa adicional de control semántico y contractual. Su aporte es reducir contradicciones, alucinaciones contextuales y respuestas que parecen razonables pero no reflejan realmente lo recuperado.</div>\n          <select><option>ENABLED</option></select>\n\n          <div class=\"fieldrow\"><label>Planner contract</label><button class=\"helpbtn\" data-help=\"h-contract\">i</button></div>\n          <div id=\"h-contract\" class=\"fieldhelp\">Planner contract define el formato exacto en que el planner puede expresar sus decisiones. En lugar de dejar que el modelo invente libremente cualquier estructura, se fija un contrato explícito y validable. Esto hace que el sistema sea más modular y portable, porque las etapas posteriores reciben una interfaz clara y no dependen de interpretar texto libre cambiante en cada versión.</div>\n          <select><option>PYDANTIC DISCRIMINATED UNION</option></select>\n\n          <div class=\"fieldrow\"><label>Semantic layer</label><button class=\"helpbtn\" data-help=\"h-semantic\">i</button></div>\n          <div id=\"h-semantic\" class=\"fieldhelp\">Semantic layer es una capa común de significado sobre métricas, entidades y relaciones del dominio. Su objetivo es que diferentes partes del sistema hablen el mismo idioma lógico aunque cambien los modelos o fuentes de datos. En una arquitectura bien diseñada, esta capa reduce ambigüedades, evita hardcodeo implícito del corpus y facilita que el producto evolucione sin degradarse.</div>\n          <select><option>METRICFLOW-STYLE REGISTRY</option></select>\n        </div>\n\n        <div class=\"card\"><h3>RUNTIME / SESSION</h3>\n          <div class=\"stats\">\n            <div class=\"stat\"><span>Multi-user</span>ENABLED<div class=\"statdetail\">Permite usuarios distintos manteniendo sus contextos separados.</div></div>\n            <div class=\"stat\"><span>Multi-session</span>ENABLED<div class=\"statdetail\">Permite varias sesiones independientes por usuario.</div></div>\n            <div class=\"stat\"><span>Fail closed</span>ENABLED<div class=\"statdetail\">Si falta una condición necesaria, el sistema se detiene en vez de improvisar.</div></div>\n            <div class=\"stat\"><span>Runtime owner</span>ENABLED<div class=\"statdetail\">Evita que dos procesos controlen simultáneamente el mismo runtime.</div></div>\n            <div class=\"stat\"><span>Zero Ghost</span>ENABLED<div class=\"statdetail\">Evita archivos o estados antiguos que puedan confundirse con la versión activa.</div></div>\n            <div class=\"stat\"><span>Checkpoint</span>ENABLED<div class=\"statdetail\">Mantiene estado verificable para continuidad y recuperación.</div></div>\n          </div>\n\n          <div class=\"fieldrow\"><label>Deployment</label><button class=\"helpbtn\" data-help=\"h-deploy\">i</button></div>\n          <div id=\"h-deploy\" class=\"fieldhelp\">Deployment resume el patrón operativo de ejecución. En este caso, la configuración expresa que un solo nodo lógico puede atender múltiples usuarios preservando aislamiento de sesión. Este tipo de descripción no es cosmética: explica cómo se espera que escale el sistema, qué se comparte y qué debe permanecer desacoplado para sostener multiusuario sin mezclar estados ni identidad.</div>\n          <select><option>single-node / multi-user</option></select>\n\n          <div class=\"fieldrow\"><label>Knowledge root</label><button class=\"helpbtn\" data-help=\"h-kb\">i</button></div>\n          <div id=\"h-kb\" class=\"fieldhelp\">Knowledge root señala la ubicación externa de la base de conocimiento que usa el sistema. Es importante que esta ruta viva como configuración y no embebida en la lógica del producto, porque así se conserva el principio corpus-agnostic by design. Dicho de forma simple: los documentos son datos de entrada, no especificaciones encubiertas del software.</div>\n          <input value=\"External configuration\" disabled>\n        </div>\n      </div>\n      <div style=\"margin-top:11px;display:flex;gap:9px;align-items:center;flex-wrap:wrap\"><button id=\"applyRag\" class=\"apply\">APPLY CONFIGURATION</button><span id=\"ragStatus\" class=\"status\">Sin cambios pendientes.</span></div>\n    </section>\n\n    <section id=\"page-workflow\" class=\"section hidden\">\n      <div class=\"titlebar\">\n        <strong>CHAT + LIVE WORKFLOW</strong>\n        <div class=\"viewbar\">\n          <span class=\"status\">LLM ORCHESTRATOR SIEMPRE ACTIVO · RAG / AGENT son capacidades seleccionables</span>\n        </div>\n      </div>\n\n      <div class=\"card chatCard\">\n        <h3>CHAT · EJECUCIÓN EN TIEMPO REAL</h3>\n        <div id=\"chat\" class=\"chat\"><div class=\"msg\">Sistema · pipeline listo.</div></div>\n        <form id=\"chatForm\" class=\"composer\"><input id=\"query\" placeholder=\"Escribe una consulta...\"><button class=\"send\" type=\"submit\">ENVIAR</button></form>\n      </div>\n\n      <div class=\"card diagramCard\">\n        <div class=\"diagramHeader\">\n          <h3 style=\"margin:0\">ÁRBOL DE EJECUCIÓN EN TIEMPO REAL</h3>\n          <div class=\"tools\">\n            <button id=\"smaller\" class=\"toolbtn square\" title=\"Reducir árbol\">−</button>\n            <button id=\"larger\" class=\"toolbtn square\" title=\"Aumentar árbol\">+</button>\n            <span id=\"zoomLabel\" class=\"status\">100%</span>\n          </div>\n        </div>\n        <div class=\"canvasFrame booting\">\n          <div id=\"zoomStage\" class=\"zoomStage\">\n            <div id=\"canvas\" class=\"canvas\">\n              <svg id=\"edges\" class=\"edges\" viewBox=\"0 0 1400 1080\" preserveAspectRatio=\"none\">\n                <defs><marker id=\"arrowhead\" markerWidth=\"8\" markerHeight=\"8\" refX=\"7\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#60a5fa\"/></marker></defs>\n              </svg>\n            </div>\n          </div>\n        </div>\n        <div class=\"legend\"><span><i class=\"dot\" style=\"background:#38bdf8\"></i>activo</span><span><i class=\"dot\" style=\"background:#2563eb\"></i>completado</span><span><i class=\"dot\" style=\"background:#24598f\"></i>pendiente</span></div>\n        <div id=\"nodeInfo\" class=\"info\"><strong>Explicaciones restauradas</strong><p>Haz clic en cualquier cajón o en su botón de información. Aquí verás una explicación resumida del nodo seleccionado, mientras que el botón (i) del propio cajón abre una tarjeta desplegable junto a ese nodo. De esa forma puedes inspeccionar el árbol sin perder contexto visual y cerrar cada explicación cuando ya no la necesites.</p></div>\n      </div>\n    </section>\n\n    <section id=\"page-agent\" class=\"section hidden\">\n      <div class=\"titlebar\"><strong>AGENT CONFIGURATION</strong><span class=\"pill on\">AGENT ON</span></div>\n      <div class=\"grid2\">\n        <div class=\"card\"><h3>PROVIDER · PER SESSION</h3>\n          <div class=\"fieldrow\"><label>Provider</label><button class=\"helpbtn\" data-help=\"h-provider\">i</button></div>\n          <div id=\"h-provider\" class=\"fieldhelp\">Provider selecciona qué motor de agente se usa dentro de la sesión actual. La arquitectura correcta trata a Hermes u OpenClaw como proveedores reemplazables detrás de una interfaz estable, no como dependencias que capturan toda la lógica del sistema. Por eso esta elección debe poder cambiar sin romper el resto del flujo ni obligar a reescribir la capa de presentación.</div>\n          <select id=\"provider\"><option value=\"hermes\">Hermes</option><option value=\"openclaw\">OpenClaw</option></select>\n          <div class=\"fieldrow\"><label>Agent timeout</label><button class=\"helpbtn\" data-help=\"h-agenttimeout\">i</button></div>\n          <div id=\"h-agenttimeout\" class=\"fieldhelp\">Agent timeout define el tiempo máximo que puede consumir una ejecución del agente antes de ser considerada fallida. Este parámetro protege a la sesión de esperas excesivas, herramientas colgadas o proveedores lentos. En entornos reales, un buen timeout evita que el usuario quede cautivo de procesos inciertos y fuerza al sistema a comportarse de manera más predecible y operable.</div>\n          <input type=\"number\" value=\"180\">\n          <div class=\"stats\"><div class=\"stat\"><span>Grounding first</span>YES</div><div class=\"stat\"><span>Fail closed</span>YES</div><div class=\"stat\"><span>Session isolation</span>YES</div><div class=\"stat\"><span>Secrets</span>EXTERNAL</div></div>\n        </div>\n        <div id=\"hermesBox\" class=\"card\"><h3>HERMES</h3>\n          <label>Command</label><input value=\"hermes\"><label>Workspace</label><input value=\"default\"><label>Model</label><input value=\"host default\">\n          <div class=\"split\"><div><label>Max turns</label><input type=\"number\" value=\"12\"></div><div><label>Toolsets</label><input value=\"all\"></div></div>\n        </div>\n        <div id=\"openclawBox\" class=\"card hidden\"><h3>OPENCLAW</h3>\n          <label>Command</label><input value=\"openclaw\"><label>Agent ID</label><input value=\"default\"><label>Model</label><input value=\"host default\">\n          <div class=\"split\"><div><label>Thinking</label><select><option>default</option><option>on</option><option>off</option></select></div><div><label>Local</label><select><option>false</option><option>true</option></select></div></div>\n        </div>\n        <div class=\"card\"><h3>AGENT CONTRACT</h3><div class=\"stats\"><div class=\"stat\"><span>Input</span>Grounded context</div><div class=\"stat\"><span>Router</span>Typed provider</div><div class=\"stat\"><span>Tools</span>Provider-owned</div><div class=\"stat\"><span>Handle</span>Checkpointed</div></div></div>\n      </div>\n    </section>\n  </main>\n</div>\n<script>\nwindow.__MINIRAG_UI_BOOT__='html';\nwindow.addEventListener('error',function(e){\n  var box=document.getElementById('nodeInfo');\n  if(box){box.innerHTML='<strong>UI RUNTIME ERROR</strong><p>'+String(e.message||'unknown')+'</p>';}\n});\n</script>\n<script>\nwindow.__MINIRAG_UI_BOOT__='js';\n\n(()=>{\n const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];\n const canvas=$('#canvas'), svg=$('#edges');\n let activeModes=new Set(['llm','rag']), selectedId=null, runTimer=null, zoom=1.00;\n let TURN_ACTIVE=false, GRAPH_BOOTSTRAPPED=false;\n let SESSION=(globalThis.crypto?.randomUUID?.()||('s-'+Date.now()+'-'+Math.random().toString(16).slice(2))), BACKEND=null, primaryMode='rag', EVENTS={};\n const sizes={};\n const defs={\n  session:{t:'SESSION / TENANCY',s:'Usuario, tenant y sesión',d:'Aísla identidad, tenant, estado conversacional y configuración por sesión.',io:'Entrada: usuario/sesión. Salida: contexto aislado.',why:'Evita contaminación entre usuarios y sesiones.'},\n  langgraph:{t:'LANGGRAPH ROUTER',s:'Single workflow authority',d:'Único orquestador global. Selecciona capacidades y controla las transiciones del workflow.',io:'Entrada: consulta + estado. Salida: ruta del grafo.',why:'Elimina routers y planners globales duplicados.'},\n  retrieval:{t:'HYBRID RETRIEVAL',s:'Semantic + BM25',d:'Recupera candidatos combinando búsqueda semántica y lexical.',io:'Entrada: query. Salida: candidatos.',why:'Mejora recall sin depender de una sola técnica.'},\n  rrf:{t:'RRF FUSION',s:'Reciprocal Rank Fusion',d:'Fusiona rankings lexical y semántico sin mezclar escalas crudas.',io:'Entrada: rankings. Salida: ranking fusionado.',why:'Patrón comunitario simple y robusto.'},\n  rerank:{t:'BGE RERANKER',s:'Cross-encoder',d:'Reordena candidatos por relevancia query-documento.',io:'Entrada: candidatos. Salida: ranking rerankeado.',why:'Aumenta precisión antes del grounding.'},\n  ground:{t:'GROUNDING GATE',s:'Evidence-only',d:'Autoriza únicamente evidencia suficiente y falla cerrado si no existe.',io:'Entrada: evidencia. Salida: contexto autorizado.',why:'Evita respuestas no sustentadas.'},\n  semantic:{t:'SEMANTIC LAYER',s:'Metric registry',d:'Gobierna métricas, series, dimensiones y relaciones.',io:'Entrada: IDs/metrics. Salida: semántica validada.',why:'Evita hardcoding y ambigüedad de negocio.'},\n  planner:{t:'TYPED PLANNER',s:'Pydantic contract',d:'El LLM interpreta la intención y produce un contrato tipado.',io:'Entrada: intención. Salida: plan validado.',why:'El planner no puede inventar operaciones fuera del schema.'},\n  executor:{t:'EXECUTOR',s:'Deterministic compute',d:'Ejecuta cálculos y escenarios de forma determinística.',io:'Entrada: plan. Salida: resultados.',why:'Es la autoridad numérica, no el LLM.'},\n  agentrouter:{t:'AGENT ROUTER',s:'Provider per session',d:'Selecciona Hermes u OpenClaw por sesión.',io:'Entrada: contexto grounded. Salida: provider seleccionado.',why:'Mantiene el Agent Plane desacoplado del core.'},\n  provider:{t:'AGENT ADAPTER',s:'Hermes / OpenClaw',d:'Frontera única hacia el runtime agéntico externo; no vuelve a rutear el workflow global.',io:'Entrada: task. Salida: ejecución del agente.',why:'LangGraph decide la ruta; el adapter sólo ejecuta el provider configurado.'},\n  tools:{t:'AGENT TOOLS',s:'Provider-owned tools',d:'Herramientas gobernadas por el runtime agentico.',io:'Entrada: tool call. Salida: observación.',why:'No duplicamos políticas ni implementaciones externas.'},\n  llm:{t:'LLM',s:'Generation / reasoning model',d:'Modelo de razonamiento y generación. No controla el workflow global.',io:'Entrada: contexto autorizado. Salida: generación.',why:'LangGraph orquesta; el LLM se concentra en tareas cognitivas.'},\n  response:{t:'RESPONSE',s:'Final output',d:'Entrega el resultado final producido por el modelo y las capacidades ejecutadas por LangGraph.',io:'Entrada: resultados autorizados del flujo. Salida: respuesta final.',why:'Punto común de salida con trazabilidad de la ruta real.'}\n };\n const flows={rag:['session','langgraph','retrieval','rrf','rerank','ground','semantic','planner','executor','llm','response'],llm:['session','langgraph','llm','response'],agent:['session','langgraph','provider','tools','llm','response']};\n const MODE_ORDER=['rag','llm','agent'];\n function currentModes(){return MODE_ORDER.filter(m=>activeModes.has(m))}\n function currentNodeIds(){\n   const seen=new Set(),out=[];\n   currentModes().forEach(m=>flows[m].forEach(id=>{if(!seen.has(id)){seen.add(id);out.push(id)}}));\n   return out;\n }\nfunction currentEdges(){\n   const E=[],seen=new Set();\n   const add=(a,b)=>{const k=a+'>'+b;if(!seen.has(k)){seen.add(k);E.push([a,b])}};\n   add('session','langgraph');\n   if(activeModes.has('rag')){\n     add('langgraph','retrieval'); add('retrieval','rrf'); add('rrf','rerank'); add('rerank','ground'); add('ground','llm');\n     add('langgraph','semantic'); add('semantic','planner'); add('planner','executor'); add('executor','llm');\n   }else if(activeModes.has('agent')){\n     add('langgraph','provider'); add('provider','tools'); add('tools','llm');\n   }else{\n     add('langgraph','llm');\n   }\n   add('llm','response');\n   return E;\n }\n const networkPos={session:[40,40],langgraph:[235,40],retrieval:[430,40],rrf:[625,40],rerank:[820,40],ground:[1015,40],semantic:[335,180],planner:[540,180],executor:[745,180],provider:[1070,260],tools:[855,300],llm:[520,180],response:[620,300]};\n\n function showPage(name){['config','workflow','agent'].forEach(p=>$('#page-'+p).classList.toggle('hidden',p!==name));$$('.tab').forEach(b=>b.classList.toggle('on',b.dataset.page===name))}\n $$('.tab').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));\n\n function syncModeButtons(){\n   activeModes.add('llm');\n   $$('[data-mode]').forEach(b=>{\n     const locked=b.dataset.mode==='llm';\n     b.classList.toggle('on',locked||activeModes.has(b.dataset.mode));\n     b.classList.toggle('locked',locked);\n     b.setAttribute('aria-disabled',locked?'true':'false');\n   });\n   $('#agentTab').classList.toggle('hidden',!activeModes.has('agent'));\n }\n async function backendMode(m){\n   const controller=new AbortController();\n   const timer=setTimeout(()=>controller.abort(),8000);\n   try{\n     const r=await fetch('/api/mode/'+m+'?session_id='+encodeURIComponent(SESSION),{\n       method:'POST',\n       cache:'no-store',\n       signal:controller.signal\n     });\n     if(!r.ok) throw new Error((await r.text())||('HTTP '+r.status));\n     primaryMode=m;\n     MODE_SYNC_ERROR=null;\n     return true;\n   }finally{\n     clearTimeout(timer);\n   }\n }\n let MODE_SYNC_ERROR=null;\n function repaintModes(){\n   selectedId=null;\n   syncModeButtons();\n   renderGraph();\n   applyZoom(zoom);\n }\n async function toggleMode(m){\n   if(m==='llm'){\n     activeModes.add('llm');\n     repaintModes();\n     $('#nodeInfo').innerHTML='<strong>LLM · SIEMPRE ACTIVO</strong><p>LangGraph es el orquestador. RAG y AGENT son capacidades seleccionables; el modelo LLM permanece disponible para generación y razonamiento.</p>';\n     return;\n   }\n\n   if(activeModes.has(m)){\n     activeModes.delete(m);\n     repaintModes();\n\n     if(primaryMode===m){\n       const next='llm';\n       $('#nodeInfo').innerHTML='<strong>'+next.toUpperCase()+' seleccionado</strong><p>Sincronizando con backend…</p>';\n       try{\n         await backendMode(next);\n         repaintModes();\n         $('#nodeInfo').innerHTML='<strong>'+next.toUpperCase()+' sincronizado</strong><p>Modo real confirmado por backend.</p>';\n       }catch(err){\n         MODE_SYNC_ERROR=String(err.message||err);\n         $('#nodeInfo').innerHTML='<strong>UI ACTIVA · BACKEND NO SINCRONIZADO</strong><p>'+MODE_SYNC_ERROR+'</p>';\n       }\n     }\n     return;\n   }\n\n   activeModes.delete(m==='rag'?'agent':'rag');\n   activeModes.add('llm');\n   activeModes.add(m);\n   primaryMode=m;\n   MODE_SYNC_ERROR='PENDING';\n   repaintModes();\n   $('#nodeInfo').innerHTML='<strong>'+m.toUpperCase()+' seleccionado</strong><p>Sincronizando con backend…</p>';\n\n   try{\n     await backendMode(m);\n     repaintModes();\n     $('#nodeInfo').innerHTML='<strong>'+m.toUpperCase()+' sincronizado</strong><p>Modo real confirmado por backend.</p>';\n   }catch(err){\n     MODE_SYNC_ERROR=String(err.message||err);\n     $('#nodeInfo').innerHTML='<strong>UI ACTIVA · BACKEND NO SINCRONIZADO</strong><p>'+MODE_SYNC_ERROR+'</p>';\n   }\n }\n $$('[data-mode]').forEach(b=>b.addEventListener('click',e=>{\n   e.preventDefault();\n   toggleMode(b.dataset.mode);\n }));\n\nfunction treePositions(ids){\n   const hasRag=activeModes.has('rag');\n   const hasLlm=activeModes.has('llm');\n   const hasAgent=activeModes.has('agent');\n\n   let cols=[];\n   if(hasRag) cols.push('rag');\n   if(hasLlm) cols.push('llm');\n   if(hasAgent) cols.push('agent');\n\n   const xmap={};\n   if(cols.length===1){\n     xmap[cols[0]]=610;\n   }else if(cols.length===2){\n     xmap[cols[0]]=350; xmap[cols[1]]=870;\n   }else{\n     xmap.rag=170; xmap.llm=610; xmap.agent=1050;\n   }\n\n   const p={session:[610,25],langgraph:[610,125],response:[610,975]};\n\n   if(hasRag){\n     const x=xmap.rag;\n     p.retrieval=[x,235]; p.rrf=[x,335]; p.rerank=[x,435];\n     p.ground=[x,535]; p.semantic=[x,635]; p.planner=[x,735]; p.executor=[x,835];\n   }\n\n   if(hasLlm){\n     p.llm=[xmap.llm,435];\n   }\n\n   if(hasAgent){\n     const x=xmap.agent;\n     p.provider=[x,400];\n     p.tools=[x,620];\n   }\n\n   return Object.fromEntries(ids.map(id=>[id,p[id]||[610,500]]));\n }\n function graphPositions(ids){return treePositions(ids)}\n const EVENT_NODE={input:'session',router:'langgraph',langgraph_router:'langgraph',context:'langgraph',retrieval:'retrieval',embeddings:'retrieval',dense:'retrieval',bm25:'retrieval',rrf:'rrf',reranker:'rerank',evidence:'ground',structured:'semantic',planner:'planner',executor:'executor',grounding:'ground',llm:'llm',agent_router:'langgraph',agent_provider:'provider',agent_tools:'tools',response:'response'};\n function eventNode(key,event){\n   const raw=String(event?.node||event?.stage||event?.component||key||'').toLowerCase();\n   return EVENT_NODE[raw]||raw;\n }\n function paintEvents(){\n   const route=new Set(currentNodeIds());\n   const actualDone=new Set(), actualActive=new Set();\n\n   for(const [k,e] of Object.entries(EVENTS)){\n     const id=eventNode(k,e);\n     const targets=id==='semantic'?['semantic','planner','executor']:[id];\n     targets.forEach(t=>{\n       const status=String(e?.status||'').toLowerCase();\n       if(status==='executing'||status==='running'||status==='started') actualActive.add(t);\n       else actualDone.add(t);\n     });\n   }\n\n   $$('.node').forEach(n=>{\n     const id=n.dataset.id;\n     n.classList.remove('active','done','inflight');\n     if(actualActive.has(id)) n.classList.add('active');\n     else if(actualDone.has(id)) n.classList.add('done');\n     else if(TURN_ACTIVE&&route.has(id)) n.classList.add('inflight');\n   });\n\n   $$('.edge').forEach(edge=>{\n     const from=edge.dataset.from, to=edge.dataset.to;\n     edge.classList.remove('active','done','inflight');\n     if(actualActive.has(to)) edge.classList.add('active');\n     else if(actualDone.has(from)&&actualDone.has(to)) edge.classList.add('done');\n     else if(TURN_ACTIVE&&route.has(from)&&route.has(to)) edge.classList.add('inflight');\n   });\n }\n function clearGraph(){[...canvas.querySelectorAll('.node')].forEach(n=>n.remove());[...canvas.querySelectorAll('.nodepopover')].forEach(n=>n.remove());[...svg.querySelectorAll('.edge')].forEach(e=>e.remove())}\n\n\n function makeNode(id,pos){\n   const n=document.createElement('div');\n   n.className='node';n.dataset.id=id;\n   n.style.left=pos[0]+'px';n.style.top=pos[1]+'px';n.style.width=(sizes[id]||180)+'px';\n\n   const body=document.createElement('button');\n   body.type='button';\n   body.className='nodebody';\n   body.innerHTML='<b>'+defs[id].t+'</b><small>'+defs[id].s+'</small>';\n   body.addEventListener('click',()=>selectNode(id));\n\n   const info=document.createElement('button');\n   info.type='button';\n   info.className='nodeinfo';\n   info.setAttribute('aria-label','Explicar '+defs[id].t);\n   info.title='Explicar';\n   info.textContent='i';\n   info.addEventListener('click',e=>{e.stopPropagation();toggleNodePopover(id)});\n\n   const pop=document.createElement('div');\n   pop.className='nodepopover';\n   pop.id='nodepop-'+id;\n   pop.innerHTML=\n     '<h4>'+defs[id].t+'</h4>'+\n     '<p>'+defs[id].d+' '+defs[id].why+'</p>'+\n     '<p class=\"meta\"><b>Entrada / salida:</b> '+defs[id].io+'</p>'+\n     '<button type=\"button\" class=\"closemini\">Cerrar</button>';\n   pop.querySelector('.closemini').addEventListener('click',e=>{e.stopPropagation();pop.classList.remove('open')});\n\n   n.appendChild(body);\n   n.appendChild(info);\n   canvas.appendChild(n);\n   canvas.appendChild(pop);\n\n   requestAnimationFrame(()=>{\n     const left=pos[0]+Math.max(0,((sizes[id]||180)-280)/2);\n     const top=pos[1]+82;\n     pop.style.left=Math.max(10,Math.min(1000,left))+'px';\n     pop.style.top=top+'px';\n   });\n }\n function toggleNodePopover(id){\n   $$('.nodepopover').forEach(p=>{\n     if(p.id!=='nodepop-'+id)p.classList.remove('open');\n   });\n   const pop=$('#nodepop-'+id);\n   if(!pop)return;\n   pop.classList.toggle('open');\n   selectNode(id);\n }\n function selectNode(id){\n   const panel=$('#nodeInfo');\n   if(selectedId===id && !panel.classList.contains('collapsed')){\n     selectedId=null;\n     $$('.node').forEach(n=>n.classList.remove('selected'));\n     panel.classList.add('collapsed');\n     return;\n   }\n   selectedId=id;\n   $$('.node').forEach(n=>n.classList.toggle('selected',n.dataset.id===id));\n   const d=defs[id];\n   panel.classList.remove('collapsed');\n   panel.innerHTML='<strong>'+d.t+'</strong><p>'+d.d+'</p><p><b>Entrada / salida:</b> '+d.io+'</p><p><b>Por qué existe:</b> '+d.why+'</p>';\n }\n function center(n){return{x:parseFloat(n.style.left)+n.offsetWidth/2,y:parseFloat(n.style.top)+n.offsetHeight/2}}\nfunction drawEdges(){\n   [...svg.querySelectorAll('.edge')].forEach(e=>e.remove());\n   const edgePairs=currentEdges();\n\n   for(const [from,to] of edgePairs){\n     const a=canvas.querySelector('.node[data-id=\"'+from+'\"]');\n     const b=canvas.querySelector('.node[data-id=\"'+to+'\"]');\n     if(!a||!b)continue;\n\n     const ax=parseFloat(a.style.left)+a.offsetWidth/2;\n     const ay=parseFloat(a.style.top)+a.offsetHeight;\n     const bx=parseFloat(b.style.left)+b.offsetWidth/2;\n     const by=parseFloat(b.style.top);\n\n     const path=document.createElementNS('http://www.w3.org/2000/svg','path');\n     path.setAttribute('class','edge');\n     path.dataset.from=from;\n     path.dataset.to=to;\n\n     const midY=ay + Math.max(28,(by-ay)/2);\n     path.setAttribute(\n       'd',\n       'M '+ax+' '+ay+\n       ' L '+ax+' '+midY+\n       ' L '+bx+' '+midY+\n       ' L '+bx+' '+by\n     );\n     svg.appendChild(path);\n   }\n }\n function renderGraph(){\n   clearTimeout(runTimer);clearGraph();const ids=currentNodeIds(),pos=graphPositions(ids);ids.forEach(id=>makeNode(id,pos[id]));\n   requestAnimationFrame(()=>{\n     drawEdges();\n     paintEvents();\n     if(!GRAPH_BOOTSTRAPPED){\n       requestAnimationFrame(()=>{\n         const frame=$('.canvasFrame');\n         if(frame){frame.scrollTop=0;frame.scrollLeft=0;frame.classList.remove('booting')}\n         GRAPH_BOOTSTRAPPED=true;\n       });\n     }\n   });\n   if(selectedId&&ids.includes(selectedId))selectNode(selectedId);\n   else $('#nodeInfo').innerHTML='<strong>ÁRBOL '+currentModes().map(x=>x.toUpperCase()).join(' + ')+' · '+Math.round(zoom*100)+'%</strong><p>LANGGRAPH es el orquestador único. El LLM permanece disponible como modelo; RAG y AGENT son capacidades seleccionables y mutuamente exclusivas en el contrato actual del backend. Ejecución primaria real: '+primaryMode.toUpperCase()+'. Durante un turno real, la ruta participante pulsa; los eventos confirmados quedan marcados como completados.</p>';\n }\n\n\n function applyZoom(next){\n   zoom=Math.max(.70,Math.min(1.30,next));\n   $('#zoomStage').style.transform='scale('+zoom+')';\n   $('#zoomLabel').textContent=Math.round(zoom*100)+'%';\n }\n $('#smaller').addEventListener('click',()=>applyZoom(zoom-.05));\n $('#larger').addEventListener('click',()=>applyZoom(zoom+.05));\n \n function enableDrag(n){ return n; }\n\n function chatMsg(text,kind='Sistema'){\n   const d=document.createElement('div'); d.className='msg'; d.textContent=kind+' · '+text;\n   $('#chat').appendChild(d); $('#chat').scrollTop=$('#chat').scrollHeight;\n }\n function consumeEvent(y){\n   const key=y?.node||y?.stage||y?.component;\n   if(key){ EVENTS[key]=y; paintEvents(); }\n   if(y.type==='answer'){ EVENTS.response={status:'completed'}; paintEvents(); chatMsg(y.text||'','RAG'); }\n   if(y.type==='error'){ TURN_ACTIVE=false; paintEvents(); chatMsg(y.text||'Error','ERROR'); }\n   if(y.type==='done'){ TURN_ACTIVE=false; paintEvents(); }\n }\n async function executeReal(q){\n   if(MODE_SYNC_ERROR){\n     throw new Error('MODE_NOT_SYNCHRONIZED: '+MODE_SYNC_ERROR);\n   }\n   EVENTS={}; TURN_ACTIVE=true; renderGraph(); chatMsg(q,'Tú'); chatMsg('ejecutando '+primaryMode.toUpperCase()+' con backend '+String(BACKEND?.version||'activo')+'…','Sistema');\n   const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,session_id:SESSION})});\n   if(!r.ok) throw new Error(await r.text());\n   const turn=await r.json();\n   const es=new EventSource('/api/events/'+encodeURIComponent(turn.turn_id));\n   es.onmessage=e=>{try{const y=JSON.parse(e.data);consumeEvent(y);if(y.type==='done')es.close()}catch(_){}};\n   es.onerror=async()=>{\n     es.close();\n     try{\n       const tr=await fetch('/api/turn/'+encodeURIComponent(turn.turn_id),{cache:'no-store'});\n       const z=await tr.json();\n       if(z.status==='completed'){EVENTS.response={status:'completed'};chatMsg(z.answer||'','RAG')}\n       else if(z.status==='failed') chatMsg(z.error||'Error','ERROR');\n     }catch(_){}\n     TURN_ACTIVE=false;\n     paintEvents();\n   };\n }\n $('#chatForm').addEventListener('submit',e=>{\n   e.preventDefault(); const q=$('#query').value.trim(); if(!q)return; $('#query').value='';\n   executeReal(q).catch(err=>chatMsg(err.message,'ERROR'));\n });\n  function mountHelpPopovers(root=document){\n   root.querySelectorAll('.helpbtn[data-help]').forEach(b=>{\n     if(b.dataset.helpBound==='1')return;\n     const box=document.getElementById(b.dataset.help);\n     const row=b.closest('.fieldrow');\n     if(box&&row&&box.parentElement!==row)row.appendChild(box);\n     b.dataset.helpBound='1';\n     b.addEventListener('click',e=>{\n       e.preventDefault();e.stopPropagation();\n       $('.fieldhelp.open').forEach(x=>{if(x!==box)x.classList.remove('open')});\n       if(box)box.classList.toggle('open');\n     });\n   });\n }\n mountHelpPopovers();\n document.addEventListener('click',e=>{if(!e.target.closest('.fieldrow'))$('.fieldhelp.open').forEach(x=>x.classList.remove('open'))});\n document.addEventListener('keydown',e=>{if(e.key==='Escape')$('.fieldhelp.open').forEach(x=>x.classList.remove('open'))});\n $('.stat').forEach(s=>s.addEventListener('click',()=>s.classList.toggle('open')));\n $('#provider').addEventListener('change',async()=>{\n   const h=$('#provider').value==='hermes';\n   $('#hermesBox').classList.toggle('hidden',!h); $('#openclawBox').classList.toggle('hidden',h);\n   const r=await fetch('/api/agent/provider/'+$('#provider').value+'?session_id='+encodeURIComponent(SESSION),{method:'POST'});\n   if(!r.ok) $('#nodeInfo').innerHTML='<strong>AGENT ERROR</strong><p>'+await r.text()+'</p>';\n });\n function card(title){return $$('.card').find(c=>c.querySelector('h3')?.textContent.trim()===title)}\n function setSelect(el,vals,current){ if(!el)return; const a=[...new Set([current,...(vals||[])].filter(v=>v!==undefined&&v!==null&&v!==''))]; el.innerHTML=a.map(v=>'<option value=\"'+String(v).replace(/\"/g,'&quot;')+'\">'+v+'</option>').join(''); el.value=String(current??''); }\n function bindConfig(){\n   if(!BACKEND)return;\n   const mc=card('MODEL PLANE'), rc=card('RETRIEVAL');\n   const ms=mc?.querySelectorAll('select')||[], mi=mc?.querySelectorAll('input')||[];\n   setSelect(ms[0],BACKEND.models?.generative,BACKEND.config.llm);\n   setSelect(ms[1],BACKEND.models?.generative,BACKEND.config.planner_model);\n   setSelect(ms[2],BACKEND.models?.embedding,BACKEND.config.embed_model);\n   if(mi[0])mi[0].value=BACKEND.config.num_ctx??mi[0].value;\n   if(mi[1])mi[1].value=BACKEND.config.timeout??mi[1].value;\n   const rs=rc?.querySelectorAll('select')||[], ri=rc?.querySelectorAll('input')||[];\n   setSelect(rs[2],BACKEND.models?.reranker,BACKEND.config.reranker_model);\n   if(ri[0])ri[0].value=BACKEND.config.evidence_top_k??ri[0].value;\n   if(ri[1])ri[1].value=BACKEND.config.bge_floor??ri[1].value;\n   [rs[0],rs[1],...((card('GROUNDING / CONTRACTS')?.querySelectorAll('select'))||[])].filter(Boolean).forEach(x=>x.disabled=true);\n }\n function configValues(){\n   const v={...(BACKEND?.config||{})}, mc=card('MODEL PLANE'),rc=card('RETRIEVAL');\n   const ms=mc.querySelectorAll('select'),mi=mc.querySelectorAll('input'),rs=rc.querySelectorAll('select'),ri=rc.querySelectorAll('input');\n   v.llm=ms[0].value; v.planner_model=ms[1].value; v.embed_model=ms[2].value; v.reranker_model=rs[2].value;\n   v.num_ctx=mi[0].value; v.timeout=mi[1].value; v.evidence_top_k=ri[0].value; v.bge_floor=ri[1].value;\n   document.querySelectorAll('[data-adv]').forEach(x=>v[x.dataset.adv]=x.value);\n   return v;\n }\n $('#applyRag').addEventListener('click',async()=>{\n   $('#ragStatus').textContent='Aplicando…';\n   const r=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({values:configValues()})});\n   if(!r.ok){$('#ragStatus').textContent='ERROR · '+await r.text();return}\n   await loadBackend(); $('#ragStatus').textContent='APLICADO · backend '+String(BACKEND?.version||'activo');\n });\n function ensureAdvanced(){\n   if($('#advancedRuntime'))return;\n   const runtime=card('RUNTIME / SESSION'); if(!runtime)return;\n   const box=document.createElement('details'); box.id='advancedRuntime'; box.style.marginTop='10px';\n   box.innerHTML='<summary class=\"status\" style=\"cursor:pointer\">ADVANCED RUNTIME PARAMETERS</summary><div class=\"split\" id=\"advancedGrid\" style=\"margin-top:8px\"></div>';\n   runtime.appendChild(box);\n   const keys=['temperature','top_p','top_k','repeat_penalty','max_output_tokens','candidates','rrf_k','evidence_relative_margin'];\n   $('#advancedGrid').innerHTML=keys.map(k=>'<div><label>'+k+'</label><input data-adv=\"'+k+'\"></div>').join('');\n }\n function ensureKnowledge(){\n   if($('#explorefiles'))return;\n   const runtime=card('RUNTIME / SESSION'); if(!runtime)return;\n   const wrap=document.createElement('div'); wrap.style.marginTop='10px';\n   wrap.innerHTML='<div class=\"fieldrow\"><label>Knowledge ingestion</label><button class=\"helpbtn\" data-help=\"h-kbingest\">i</button></div><div id=\"h-kbingest\" class=\"fieldhelp\">Carga archivos o una carpeta hacia la base de conocimiento configurada externamente. La UI valida tipos y tamaño, sube los archivos y solicita reindexación real al backend.</div><div style=\"display:flex;gap:8px;flex-wrap:wrap\"><button id=\"explorefiles\" class=\"apply\" type=\"button\">ARCHIVOS</button><button id=\"explorefolder\" class=\"apply\" type=\"button\">CARPETA</button><input id=\"pickfiles\" type=\"file\" multiple class=\"hidden\"><input id=\"pickfolder\" type=\"file\" webkitdirectory multiple class=\"hidden\"></div><div id=\"uploadstate\" class=\"status\" style=\"margin-top:7px\">Sin cargas pendientes.</div>';\n   runtime.appendChild(wrap);\n   $('#explorefiles').onclick=()=>$('#pickfiles').click(); $('#explorefolder').onclick=()=>$('#pickfolder').click();\n   $('#pickfiles').onchange=e=>uploadPicked(e.target.files,e.target); $('#pickfolder').onchange=e=>uploadPicked(e.target.files,e.target);\n   mountHelpPopovers(wrap);\n }\n async function uploadPicked(list,input){\n   const all=[...list]; if(input)input.value=''; if(!all.length)return;\n   let info={supported:[]}; try{info=await(await fetch('/api/knowledge')).json()}catch(_){}\n   const ok=new Set(info.supported||[]), max=info.max_file_bytes||Infinity, fs=[],skip=[];\n   for(const f of all){const rel=f.webkitRelativePath||f.name, name=rel.split('/').pop(), ext=name.includes('.')?name.slice(name.lastIndexOf('.')).toLowerCase():''; if(ok.size&&!ok.has(ext)){skip.push(name);continue} if(f.size>max){skip.push(name);continue} fs.push([f,rel])}\n   let done=0;\n   for(const [f,rel] of fs){$('#uploadstate').textContent='Subiendo '+rel+'…'; const path=rel.split('/').map(encodeURIComponent).join('/'); const r=await fetch('/api/knowledge/files/'+path,{method:'PUT',headers:{'Content-Type':'application/octet-stream'},body:f}); if(r.ok)done++}\n   if(done){$('#uploadstate').textContent='Indexando…'; const r=await fetch('/api/knowledge/reindex',{method:'POST'}); const x=await r.json().catch(()=>({})); $('#uploadstate').textContent='Base actualizada · '+done+' archivo(s) · '+(x.indexed??'?')+' chunks'+(skip.length?' · omitidos '+skip.length:'')}\n   else $('#uploadstate').textContent='No se cargaron archivos válidos.';\n }\n function bindAgent(){\n   const c=BACKEND?.agent_config||{}, p=BACKEND?.agent_provider||c.provider||'hermes';\n   $('#provider').value=p; $('#hermesBox').classList.toggle('hidden',p!=='hermes'); $('#openclawBox').classList.toggle('hidden',p!=='openclaw');\n   const pc=card('PROVIDER · PER SESSION'), pi=pc?.querySelectorAll('input')||[]; if(pi[0])pi[0].value=c.timeout??180;\n   const hi=$('#hermesBox')?.querySelectorAll('input')||[]; if(hi[0])hi[0].value=c.hermes_command??'hermes'; if(hi[1])hi[1].value=c.workspace??'default'; if(hi[2])hi[2].value=c.hermes_model??''; if(hi[3])hi[3].value=c.max_turns??12; if(hi[4])hi[4].value=c.hermes_toolsets??'all';\n   const oi=$('#openclawBox')?.querySelectorAll('input')||[], os=$('#openclawBox')?.querySelectorAll('select')||[]; if(oi[0])oi[0].value=c.openclaw_command??'openclaw'; if(oi[1])oi[1].value=c.openclaw_agent??'default'; if(oi[2])oi[2].value=c.openclaw_model??''; if(os[0])os[0].value=String(c.openclaw_thinking??'default'); if(os[1])os[1].value=String(Boolean(c.openclaw_local));\n   if(!$('#agentApply')){\n     const row=document.createElement('div'); row.style.cssText='margin-top:11px;display:flex;gap:9px;align-items:center;flex-wrap:wrap'; row.innerHTML='<button id=\"agentApply\" class=\"apply\" type=\"button\">APPLY AGENT CONFIGURATION</button><span id=\"agentStatus\" class=\"status\">Sin cambios pendientes.</span>'; $('#page-agent').appendChild(row);\n     $('#agentApply').onclick=applyAgent;\n   }\n }\n async function applyAgent(){\n   const c={...(BACKEND?.agent_config||{})}, pc=card('PROVIDER · PER SESSION'),pi=pc.querySelectorAll('input'),hi=$('#hermesBox').querySelectorAll('input'),oi=$('#openclawBox').querySelectorAll('input'),os=$('#openclawBox').querySelectorAll('select');\n   c.provider=$('#provider').value; c.timeout=pi[0].value; c.hermes_command=hi[0].value; c.workspace=hi[1].value; c.hermes_model=hi[2].value; c.max_turns=hi[3].value; c.hermes_toolsets=hi[4].value; c.openclaw_command=oi[0].value; c.openclaw_agent=oi[1].value; c.openclaw_model=oi[2].value; c.openclaw_thinking=os[0].value; c.openclaw_local=os[1].value==='true';\n   const r=await fetch('/api/agent/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({values:c})}); if(r.ok){await loadBackend(); $('#agentStatus').textContent='APLICADO · backend '+String(BACKEND?.version||'activo')} else $('#agentStatus').textContent='ERROR · '+await r.text();\n }\n async function loadBackend(){\n   const r=await fetch('/api/status?session_id='+encodeURIComponent(SESSION),{cache:'no-store'}); if(!r.ok)throw new Error(await r.text()); BACKEND=await r.json(); primaryMode=BACKEND.mode||(BACKEND.rag?'rag':'llm'); activeModes=new Set(['llm']); if(primaryMode==='rag'||primaryMode==='agent')activeModes.add(primaryMode);\n   document.querySelector('.ver').textContent=String(BACKEND.version||'BACKEND')+' · UI TREE · NO REORDER · LIVE';\n   ensureAdvanced(); ensureKnowledge(); bindConfig(); document.querySelectorAll('[data-adv]').forEach(x=>x.value=BACKEND.config?.[x.dataset.adv]??''); bindAgent(); syncModeButtons(); renderGraph(); applyZoom(zoom);\n }\n syncModeButtons();renderGraph();applyZoom(zoom);loadBackend().catch(e=>{$('#nodeInfo').innerHTML='<strong>BACKEND ERROR</strong><p>'+e.message+'</p>'});\n})();\n\n</script>\n</body>\n</html>";

function out(statusCode, body, contentType, cacheControl) {
  return {
    statusCode,
    headers: {
      'content-type': contentType,
      'cache-control': cacheControl,
      'x-content-type-options': 'nosniff',
      'x-mini-rag-version': '10.1.0',
      'x-mini-rag-ui-release': RELEASE
    },
    body
  };
}

exports.handler = async event => {
  const session = sessionFromEvent(event);
  if (!session) return out(401, JSON.stringify({error:'UNAUTHENTICATED'}), 'application/json; charset=utf-8', 'no-store');

  const path = String(event.queryStringParameters?.path || '').replace(/^\/+/, '');
  if (!path || path === 'index' || path === 'index.html') {
    return out(200, HTML, 'text/html; charset=utf-8', 'no-store, max-age=0');
  }
  return out(404, JSON.stringify({error:'UI_ROUTE_NOT_FOUND',release:RELEASE}), 'application/json; charset=utf-8', 'no-store');
};
